 11	/**
 12	 * The contract's documents, as TypeScript can check them.
 13	 *
 14	 * The schemas under `schemas/` are the authority, read from disk because the
 15	 * other reader of those bytes is not TypeScript — the simulator compiles the
 16	 * same files (`contract.py`) and holds every claimed spec to the spec schema.
 17	 * This is the control plane's half of the same guarantee, both ways round: a
 18	 * spec is checked *before it is sent*, so a document that does not speak the
 19	 * contract is a fault caught on the sending side rather than a refusal the
 20	 * simulator has to explain back — and a report is checked *as it arrives*,
 21	 * so nothing off the wire reaches a lifecycle write without having proven it
 22	 * speaks the contract the simulator's own check already applied on the way
 23	 * out.
 24	 *
 25	 * The answer is a list of complaints rather than a thrown violation, because
 26	 * the caller's next move is not an exception's: one unbuildable spec is
 27	 * skipped and said out loud, and the rest of the batch still goes; one
 28	 * refused report is answered with its complaints, and the simulator's log
 29	 * shows the same sentences its own check would have raised. Each complaint
 30	 * names the place and the problem — `/modality: must be equal to one of the
 31	 * allowed values` — in the same shape the simulator's check logs, so the two
 32	 * sides of the wire read alike in two languages.
 33	 */
 34	
 35	/**
 36	 * Compiled once each, on first use rather than at import, so loading the
 37	 * package for its measure catalog never pays for — or fails on — schema
 38	 * compilation. Compiling is itself part of the check: a schema that is not
 39	 * valid 2020-12 fails loudly here, rather than quietly accepting everything.
 40	 */
 41	function compileFromDisk(schemaFile: string): ValidateFunction {
 42	  const ajv = new Ajv2020({ strict: true, allErrors: true });
 43	  addFormats(ajv);
 44	  const schema: unknown = JSON.parse(
 45	    readFileSync(new URL(`../schemas/${schemaFile}`, import.meta.url), "utf8"),
 46	  );
 47	  return ajv.compile(schema as Record<string, unknown>);
 48	}
 49	
 50	let compiledSpec: ValidateFunction | undefined;
 51	let compiledReport: ValidateFunction | undefined;
 52	
 53	/**
 54	 * Everything wrong with a document by one validator's lights, or nothing.
 55	 * `allErrors`, deliberately, so one answer says everything wrong at once
 56	 * rather than one complaint per attempt.
 57	 */
 58	function complaintsFrom(
 59	  validate: ValidateFunction,
 60	  document: unknown,
 61	): readonly string[] {
 62	  if (validate(document)) return [];
 63	  return (validate.errors ?? []).map(
 64	    (error) => `${error.instancePath}: ${error.message ?? "does not validate"}`,
 65	  );
 66	}
 67	
 68	/**
 69	 * Everything wrong with one would-be spec document, or nothing.
 70	 *
 71	 * An empty answer is the green light: the document speaks the spec direction
 72	 * of the contract and a simulator holding this contract version will accept
 73	 * it. Anything else is the full list, because a log line about a skipped
 74	 * simulation should say everything wrong with it at once rather than one
 75	 * complaint per attempt that will never be retried.
 76	 */
 77	export function specComplaints(document: unknown): readonly string[] {
 78	  compiledSpec ??= compileFromDisk("simulation-spec.v3.schema.json");
 79	  return complaintsFrom(compiledSpec, document);
 80	}
 81	
 82	/**
 83	 * Everything wrong with one arrived report document, or nothing.
 84	 *
 85	 * An empty answer means the document speaks the report direction of the
 86	 * contract, and only then does the control plane read anything out of it —
 87	 * which is also where the vocabulary line is held: the endings a caller may
 88	 * report are the ones the schema enumerates, so the platform's own words
 89	 * (`orphaned` is the sweep's, `dispatch_failed` the claim path's) are refused
 90	 * here as documents rather than reasoned about as states.
 91	 */
 92	export function reportComplaints(document: unknown): readonly string[] {
 93	  compiledReport ??= compileFromDisk("simulation-report.v1.schema.json");
 94	  return complaintsFrom(compiledReport, document);
 95	}
