 42	  const ajv = new Ajv2020({ strict: true, allErrors: true });
 43	  addFormats(ajv);
 44	  const schema: unknown = JSON.parse(
 45	    readFileSync(new URL(`../schemas/${schemaFile}`, import.meta.url), "utf8"),
 46	  );
 47	  return ajv.compile(schema as Record<string, unknown>);
