   232	        'stamped on every row it takes. Send claimant as non-empty text, like ' +
   233	        '"egma-simulator-1".',
   234	    };
   235	  }
   236	  if (claimant.trim().length > 200) {
   237	    return {
   238	      refusal:
   239	        "a claimant's name fits in 200 characters; it is a label for telling " +
   240	        "two simulators apart, not a place for anything longer.",
   241	    };
   242	  }
   243	
   244	  const capacity = body.capacity;
   245	  if (typeof capacity !== "number" || !Number.isInteger(capacity) || capacity < 1) {
   246	    return {
   247	      refusal:
   248	        "a claim declares capacity — how many simulations this simulator has " +
   249	        "room to conduct at once — as a whole number of at least 1.",
   250	    };
   251	  }
   252	
   253	  const wait = body.wait_seconds;
   254	  if (
   255	    wait !== undefined &&
   256	    (typeof wait !== "number" || !Number.isFinite(wait) || wait < 0)
   257	  ) {
   258	    return {
   259	      refusal:
   260	        "wait_seconds is how long this request may be held open while the " +
   261	        "queue is empty, as a number of seconds of at least 0. Leave it out " +
   262	        `and Egma holds for ${DEFAULT_HOLD_SECONDS}.`,
   263	    };
   264	  }
