   266	  const contractVersions = body.contract_versions;
   267	  if (
   268	    !Array.isArray(contractVersions) ||
   269	    contractVersions.length === 0 ||
   270	    !contractVersions.every(
   271	      (version) => typeof version === "number" && Number.isInteger(version),
   272	    )
