   302	 * one.
   303	 *
   304	 * Everything is read through the claim's own narrowed context, so the
   305	 * assembly of one customer's spec happens inside that customer exactly as a
   306	 * person's read would. The reads can each come back empty — a connection
   307	 * deleted mid-flight, a row from before tests were pinned — and the schema
   308	 * check at the end holds whatever was assembled to the same standard the
   309	 * simulator's own check will apply on receipt.
   310	 */
   311	async function assembledSpec(
   312	  claim: SimulationClaim,
   313	  /**
   314	   * The runs already read while answering this one claim request, by id.
   315	   *
   316	   * A claim takes up to fifty conversations at once and they are usually a
   317	   * run's — that is what a run *is* — so the run header would otherwise be
   318	   * read fifty times for fifty specs that all want the same frozen world. The
   319	   * cache lives for one request and no longer: the header is frozen from the
   320	   * moment the run was created, so re-reading it inside one response could
   321	   * only ever return the same rows, and a cache that outlived the request
   322	   * would be a second copy of a record somebody may since have deleted.
   323	   *
   324	   * Keyed by run id alone, which is safe because every claim in one batch was
   325	   * read through its own row's tenancy and a run id is unique across the
   326	   * deployment — two claims naming one run are two conversations of it.
   327	   */
   328	  runs: Map<string, Run | undefined>,
   329	  retellTargets: Map<string, Promise<RetellDirectTargetCheck>>,
   330	  providerCredentials: ProviderCredentialSource,
   331	  retellFetch?: typeof fetch,
   332	  responseDeadline = Date.now() + CLAIM_RESPONSE_MILLISECONDS,
   333	): Promise<
   334	  | Record<string, unknown>
   335	  | { readonly unbuildable: string }
   336	  | { readonly retryable: string }
   337	> {
   338	  const personaVersion = await getPersonaVersion(
   339	    claim.auth,
   340	    claim.personaVersionId,
   341	  );
   342	  if (personaVersion === undefined) {
   343	    return { unbuildable: "its pinned persona version could not be read" };
   344	  }
   345	
   346	  const evidence = await getSimulationExecutionEvidence(claim.auth, claim.id);
   347	  if (evidence === undefined) {
   348	    return { unbuildable: "its pinned test version could not be read" };
   349	  }
