   600	  }
   601	  validateName(input.name);
   602	  validateTraits(traits);
   603	  const storedModels = validPersonaModels(models);
   604	
   605	  return db().transaction(async (tx) => {
   606	    await lockPersonaProject(tx, auth, projectId);
   607	    return insertPersonaWithTraits(
   608	      tx,
   609	      auth,
   610	      projectId,
   611	      input,
