   618	/**
   619	 * Hold the project a persona write lands in until that write commits.
   620	 *
   621	 * Project first is the shared lock order for a fork: lifecycle writes also
   622	 * take the project before a persona. A fork that took the source first could
   623	 * deadlock with an Archive that already held the project and was waiting for
   624	 * that same source. The shared lock also makes project deletion wait until the
   625	 * new identity and version either both commit or both roll back.
   626	 */
   627	async function lockPersonaProject(
   628	  tx: Transaction,
   629	  auth: AuthContext,
   630	  projectId: string,
   631	): Promise<void> {
   632	  const [target] = await tx
   633	    .select({ id: project.id })
   634	    .from(project)
   635	    .where(
   636	      within(
   637	        auth,
   638	        project,
   639	        and(eq(project.id, projectId), isNull(project.deletedAt)),
   640	      ),
   641	    )
   642	    .limit(1)
   643	    .for("share", { of: project });
   644	  if (target === undefined) {
   645	    throw new ProjectOutsideOrganizationError(auth.organizationId, projectId);
   646	  }
   647	}
