   649	/** Write one complete Custom persona on the caller's transaction. */
   650	async function insertPersonaWithTraits(
   651	  tx: Transaction,
   652	  auth: AuthContext,
   653	  projectId: string,
   654	  input: Pick<NewPersona, "name" | "description">,
   655	  storedTraits: PersonaTraits,
   656	  storedModels: PersonaModels,
   657	): Promise<Persona> {
   658	  const id = newId("prs");
   659	  const versionId = newId("prsv");
   660	  await tx.insert(persona).values({
   661	    id,
   662	    organizationId: auth.organizationId,
   663	    projectId,
   664	    name: input.name,
   665	    description: input.description ?? null,
   666	    currentVersionId: versionId,
   667	    createdBy: auth.userId,
   668	  });
   669	  await tx.insert(personaVersion).values({
   670	    id: versionId,
   671	    personaId: id,
   672	    version: 1,
   673	    traits: storedTraits,
   674	    models: storedModels,
   675	    createdBy: auth.userId,
   676	  });
   677	
   678	  // Read through the ordinary seam while both rows and the project lock are
   679	  // still on this transaction. This is the authoritative answer for the
   680	  // version and project-default pointer; no hand-built return value can drift
   681	  // from what a following read will see.
   682	  const inserted = await readPersonaOn(tx, auth, id);
   683	  if (inserted === undefined) {
   684	    throw new Error("the persona was not written");
   685	  }
   686	  return inserted;
   687	}
