   650	async function insertPersonaWithTraits(
   651	  tx: Transaction,
   652	  auth: AuthContext,
   653	  projectId: string,
   654	  input: Pick<NewPersona, "name" | "description">,
   655	  storedTraits: PersonaTraits,
   656	  storedModels: PersonaModels,
   657	): Promise<Persona> {
   658	  const id = newId("prs");
   659	  const versionId = newId("prsv");
   660	  await tx.insert(persona).values({
   661	    id,
   662	    organizationId: auth.organizationId,
   663	    projectId,
   664	    name: input.name,
   665	    description: input.description ?? null,
   666	    currentVersionId: versionId,
   667	    createdBy: auth.userId,
   668	  });
