   704	/**
   705	 * The identity row joined to its current version, and to the project whose
   706	 * pointer decides whether it is the default — the shape `get` and `list` both
   707	 * answer with, written once so the two can never drift.
   708	 *
   709	 * The project join is what makes "is this the default?" a fact of the read
   710	 * rather than a second question every caller would have to remember to ask.
   711	 */
   712	function selectWithCurrentVersion(auth: AuthContext, on: Queryable = db()) {
   713	  const defaultProject =
   714	    auth.projectId === undefined
   715	      ? sql`false`
   716	      : eq(project.id, auth.projectId);
   717	  return on
   718	    .select({
   719	      ...COLUMNS,
   720	      version: personaVersion.version,
   721	      versionId: personaVersion.id,
   722	      traits: personaVersion.traits,
   723	      models: personaVersion.models,
   724	      defaultPersonaId: project.defaultPersonaId,
   725	    })
   726	    .from(persona)
   727	    .innerJoin(
   728	      personaVersion,
   729	      eq(persona.currentVersionId, personaVersion.id),
   730	    )
   731	    .leftJoin(
   732	      project,
   733	      and(defaultProject, eq(project.defaultPersonaId, persona.id)),
   734	    );
   735	}
