 233	  it("copies the source version that wins the source-row lock", async () => {
 234	    const source = await createPersona(acme.auth, {
 235	      name: "Concurrent source",
 236	      traits: {
 237	        personality: "Starts as the first version.",
 238	        language: "en-US",
 239	      },
 240	    });
 241	    const nextVersionId = newId("prsv");
 242	    const nextTraits = {
 243	      personality: "Is the committed current version.",
 244	      language: "en-US",
 245	      patience: "Waits for a complete answer.",
 246	    } as const;
 247	    const holder = await openSingleConnection(database.url);
 248	    let forking: ReturnType<typeof forkPersona> | undefined;
 249	
 250	    try {
 251	      await holder.sql("begin");
 252	      const { rows: sessions } = await holder.sql<{ pid: number }>(
 253	        "select pg_backend_pid() as pid",
 254	      );
 255	      const blockerPid = sessions[0]?.pid;
 256	      if (blockerPid === undefined) throw new Error("the holder has no pid");
 257	
 258	      await holder.sql(
 259	        `insert into persona_version
 260	           (id, persona_id, version, traits, models, created_by)
 261	         values ($1, $2, 2, $3::jsonb, $4::jsonb, $5)`,
 262	        [
 263	          nextVersionId,
 264	          source.id,
 265	          JSON.stringify(nextTraits),
 266	          JSON.stringify(source.models),
