 268	        ],
 269	      );
 270	      await holder.sql(
 271	        `update persona
 272	            set current_version_id = $1,
 273	                revision = 'source-version-moved',
 274	                updated_at = now()
 275	          where id = $2`,
 276	        [nextVersionId, source.id],
 277	      );
 278	
 279	      // The old implementation read version 1 without a lock and created its
 280	      // copy while this transaction was still open. Fork must instead wait on
 281	      // this source row, then copy the version that commits.
 282	      forking = forkPersona(acme.auth, source.id);
 283	      await waitUntilBlockedBy(blockerPid);
 284	      const { rows: copiesBeforeCommit } = await database.sql<{ count: number }>(
 285	        `select count(*)::integer as count
 286	           from persona
 287	          where project_id = $1 and name = $2`,
 288	        [acme.projectId, source.name],
 289	      );
 290	      expect(copiesBeforeCommit[0]?.count).toBe(1);
 291	      await holder.sql("commit");
 292	
 293	      const fork = await forking;
 294	      expect(fork).toMatchObject({
 295	        owner: "organization",
 296	        projectId: acme.projectId,
 297	        version: 1,
 298	        traits: nextTraits,
 299	        models: source.models,
 300	        isDefault: false,
 301	      });
 302	      const { rows: copiesAfterCommit } = await database.sql<{ count: number }>(
 303	        `select count(*)::integer as count
 304	           from persona
 305	          where project_id = $1 and name = $2`,
 306	        [acme.projectId, source.name],
 307	      );
 308	      expect(copiesAfterCommit[0]?.count).toBe(2);
 309	    } finally {
 310	      await holder.sql("rollback").catch(() => undefined);
 311	      await forking?.catch(() => undefined);
 312	      await holder.close();
 313	    }
 314	  });
