 277	      );
 278	
 279	      // The old implementation read version 1 without a lock and created its
 280	      // copy while this transaction was still open. Fork must instead wait on
 281	      // this source row, then copy the version that commits.
 282	      forking = forkPersona(acme.auth, source.id);
 283	      await waitUntilBlockedBy(blockerPid);
 284	      const { rows: copiesBeforeCommit } = await database.sql<{ count: number }>(
 285	        `select count(*)::integer as count
 286	           from persona
 287	          where project_id = $1 and name = $2`,
 288	        [acme.projectId, source.name],
 289	      );
