 304	           from persona
 305	          where project_id = $1 and name = $2`,
 306	        [acme.projectId, source.name],
 307	      );
 308	      expect(copiesAfterCommit[0]?.count).toBe(2);
 309	    } finally {
 310	      await holder.sql("rollback").catch(() => undefined);
 311	      await forking?.catch(() => undefined);
 312	      await holder.close();
 313	    }
 314	  });
