    31	/** The execution mechanisms implemented by the grader service. */
    32	export const GRADER_DEFINITION_TYPES = ["llm_as_judge", "code"] as const;
    33	export type GraderDefinitionType = (typeof GRADER_DEFINITION_TYPES)[number];
    34	
    35	/** A definition version states which evidence modality it can grade. */
