    97	        '["chat", "voice"]'::jsonb,
    98	        '["voice", "chat"]'::jsonb
    99	      )`,
   100	    ),
   101	  ],
   102	);
   103	
   104	/**
   105	 * A stable grader-library identity. Null tenancy means that Egma owns it.
   106	 * `scope_editable` is catalog policy; actual scope is project policy below.
   107	 */
   108	export const graderDefinition = pgTable(
   109	  "grader_definition",
   110	  {
   111	    id: idText("id").primaryKey(),
   112	    organizationId: idText("organization_id").references(
   113	      () => organization.id,
   114	      { onDelete: "cascade" },
   115	    ),
   116	    name: text("name").notNull(),
   117	    description: text("description"),
   118	    scopeEditable: boolean("scope_editable").notNull(),
   119	    currentDefinitionVersion: integer("current_definition_version")
   120	      .notNull()
   121	      .default(1),
   122	    createdAt: createdAt(),
   123	    updatedAt: updatedAt(),
   124	  },
   125	  (table) => [
   126	    prefixCheck("grader_definition_id_prefix", table.id, "grl"),
   127	    foreignKey({
   128	      name: "grader_definition_current_version_fk",
   129	      columns: [table.id, table.currentDefinitionVersion],
   130	      foreignColumns: [
   131	        graderDefinitionVersion.definitionId,
   132	        graderDefinitionVersion.version,
   133	      ],
   134	    }),
   135	    uniqueIndex("grader_definition_predefined_name_unique")
   136	      .on(table.name)
   137	      .where(sql`${table.organizationId} is null`),
   138	    index("grader_definition_organization_id_idx").on(table.organizationId),
   139	  ],
   140	);
   141	
   142	/** One project's live policy for one shared grader definition. */
   143	export const projectGrader = pgTable(
   144	  "project_grader",
   145	  {
   146	    id: idText("id").primaryKey(),
   147	    organizationId: idText("organization_id")
   148	      .notNull()
   149	      .references(() => organization.id, { onDelete: "cascade" }),
   150	    projectId: idText("project_id").notNull(),
   151	    graderDefinitionId: idText("grader_definition_id")
