   153	      .references(() => graderDefinition.id, { onDelete: "restrict" }),
   154	    scope: jsonb("scope").$type<ProjectGraderScope>().notNull(),
   155	    parameterValues: jsonb("parameter_values")
   156	      .$type<GraderParameterValues>()
   157	      .notNull(),
   158	    passThreshold: doublePrecision("pass_threshold").notNull(),
   159	    archivedAt: moment("archived_at"),
   160	    createdAt: createdAt(),
   161	    updatedAt: updatedAt(),
   162	  },
   163	  (table) => [
   164	    prefixCheck("project_grader_id_prefix", table.id, "grd"),
   165	    foreignKey({
   166	      name: "project_grader_project_organization_fk",
   167	      columns: [table.projectId, table.organizationId],
   168	      foreignColumns: [project.id, project.organizationId],
   169	    }).onDelete("cascade"),
