   174	          is not distinct from '{}'::jsonb
   175	        and ${table.scope} ?& array['simulations', 'production']::text[]
   176	        and jsonb_typeof(${table.scope}->'simulations') is not distinct from 'array'
   177	        and (
   178	          ${table.scope}->'production' = 'null'::jsonb
   179	          or jsonb_typeof(${table.scope}->'production') is not distinct from 'object'
   180	        )`,
   120	): Promise<GraderResult> {
   121	  try {
   122	    const result = await execute({
   123	      definition: entry.definition,
   124	      parameterValues: entry.parameterValues,
   125	      conversation,
   126	      judging: { judge: judges.get(entry.projectGraderId) ?? null },
   127	      reading,
   128	    });
   129	    if (result.score === null) {
   130	      if (typeof result.details.error !== "string" || result.details.error.trim() === "") {
   131	        throw new Error("returned a null score without an error explanation");
   132	      }
   133	      return result;
   134	    }
   135	    if (!Number.isFinite(result.score) || result.score < 0 || result.score > 1) {
   136	      throw new Error(`returned score ${result.score}, outside 0 through 1`);
   137	    }
   138	    return result;
   139	  } catch (error) {
   140	    return {
   141	      score: null,
   142	      details: {
   143	        error: `this grader could not produce a score: ${
   144	          error instanceof Error ? error.message : String(error)
   145	        }`,
   146	      },
   147	    };
   148	  }
   149	}
